{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL injection vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4",
      "explanation": "The searchKey parameter is concatenated directly into a SOQL query string without any sanitization or binding. This allows an attacker to inject malicious SOQL syntax and potentially access unauthorized data or perform destructive operations.",
      "remediation": "Replace the dynamic concatenation with a bind variable by changing the query to 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50' and remove the AccessLevel.USER_MODE parameter since it's not needed for this type of query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Opportunity.Amount field",
      "severity": "Medium",
      "file": "Opportunity_Stage_Editor.permissionset-meta.xml",
      "lines": "fieldPermissions for Opportunity.Amount",
      "explanation": "The permission set grants read access to Opportunity.Amount but not edit access. However, the Apex code attempts to update the StageName field which is editable, but the query returns the Amount field which is readable only. This could lead to a FLS violation if the code were to attempt to modify or return the Amount field in a future version.",
      "remediation": "Ensure that all fields accessed in queries and DML operations have appropriate CRUD/FLS permissions. If the Amount field is not needed for the operation, remove it from the query. Otherwise, grant edit access to the Amount field in the permission set."
    },
    {
      "category": "C3",
      "title": "Missing sharing enforcement on OpportunityStageService",
      "severity": "Medium",
      "file": "OpportunityStageService.cls",
      "lines": "class declaration",
      "explanation": "The class is declared with 'with sharing' which is good, but the method is @AuraEnabled and can be called externally. The class should enforce proper sharing rules when accessed through external entry points.",
      "remediation": "Ensure that all classes reachable via @AuraEnabled methods are properly enforcing sharing rules. Since this class is already declared with 'with sharing', it's correctly enforcing sharing for internal calls, but verify that the external access pattern doesn't bypass these protections."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "ContactPhoneService.cls",
      "explanation": "The ContactPhoneService class performs a DML operation (update) without enforcing CRUD/FLS. Even though the permission set grants edit access to Contact, the code does not use Security.stripInaccessible or WITH USER_MODE to ensure that the user has proper permissions before updating the record.",
      "remediation": "Add Security.stripInaccessible() after the query and enforce CRUD/FLS by using WITH USER_MODE in SOQL or explicitly checking permissions with Security.isUpdateAllowed()."
    },
    {
      "category": "C3",
      "title": "Sharing violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "ContactPhoneService.cls",
      "explanation": "Although the class is declared with 'with sharing', it's @AuraEnabled and can be called externally. If this class were reachable from a guest profile or unauthenticated context, it could bypass record-level sharing rules.",
      "remediation": "Ensure that any @AuraEnabled method running in a shared context enforces proper sharing rules using WITH USER_MODE or Security.stripInaccessible()."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Class runs without sharing",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1",
      "explanation": "The class is declared 'without sharing', which means it ignores record-level sharing settings. This can allow users to access Case records they shouldn't be able to see based on their sharing rules or roles.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing' to enforce record-level sharing."
    },
    {
      "category": "C2",
      "title": "FLS not enforced in query results",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "10",
      "explanation": "While Security.stripInaccessible is used, it's applied after the query. The query itself does not enforce FLS, which means fields that the user shouldn't have access to might be included in the initial query results before stripping.",
      "remediation": "Use WITH SECURITY_ENFORCED or WITH USER_MODE in the SOQL query to enforce FLS at query time, rather than relying solely on Security.stripInaccessible."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "15, 16, 17, 18",
      "explanation": "The Support Agent Tools permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions. These are powerful system permissions that should only be granted to administrators or integration users with a clear need. The description indicates it's for 'tier-1 support agents', which doesn't justify such broad access.",
      "remediation": "Remove the ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions from the Support Agent Tools permission set. Instead, grant only the specific object permissions needed (like Edit Case) and minimal API access."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS violation on Product2.Family field",
      "severity": "Medium",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "fieldPermissions",
      "explanation": "The profile grants read access to the Product2.Family field but does not grant editable access. However, the Apex class PublicCatalogController retrieves this field in a query without enforcing FLS. Even though the field is readable, the code doesn't strip inaccessible fields, which could lead to unexpected behavior or data exposure if the field permissions change.",
      "remediation": "Use Security.stripInaccessible() after the SOQL query to ensure that only accessible fields are returned to the caller, or enforce FLS by using WITH SECURITY_ENFORCED in the SOQL query."
    }
  ]
}
